package com.cloudinfra.sdk.resilience;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.concurrent.atomic.AtomicLong;
import java.util.function.Supplier;
import java.util.regex.Pattern;

public class CircuitBreakerService {

    private static final int FAILURE_THRESHOLD = 5;
    private static final long RECOVERY_TIMEOUT_MS = 30000;
    private static final String TEMPLATE_BASE = "/opt/cloudinfra/templates";

    private final ConcurrentHashMap<String, CircuitState> circuits = new ConcurrentHashMap<>();
    private final TemplateRenderer renderer;

    public CircuitBreakerService(TemplateRenderer renderer) {
        this.renderer = renderer;
    }

    public <T> T execute(String circuitId, Supplier<T> operation, Supplier<T> fallback) {
        CircuitState state = circuits.computeIfAbsent(circuitId, k -> new CircuitState());

        if (state.isOpen()) {
            if (state.shouldAttemptReset()) {
                state.toHalfOpen();
            } else {
                logCircuitEvent(circuitId, "fallback", state.getFailureCount());
                return fallback.get();
            }
        }

        try {
            T result = operation.get();
            state.recordSuccess();
            logCircuitEvent(circuitId, "success", state.getFailureCount());
            return result;
        } catch (Exception e) {
            state.recordFailure();
            logCircuitEvent(circuitId, "failure", state.getFailureCount());
            if (state.getFailureCount() >= FAILURE_THRESHOLD) {
                state.toOpen();
                logCircuitEvent(circuitId, "opened", state.getFailureCount());
            }
            return fallback.get();
        }
    }

    private void logCircuitEvent(String circuitId, String event, int failureCount) {
        String logEntry = String.format("[CircuitBreaker] id=%s event=%s failures=%d",
                circuitId, event, failureCount);
        System.out.println(logEntry);
    }

    public String renderStatusPage(String serviceGroup, String locale) {
        StringBuilder statusData = new StringBuilder();
        circuits.forEach((id, state) -> {
            statusData.append(String.format("%s:%s:%d\n", id, state.getStateName(), state.getFailureCount()));
        });

        String templatePath = resolveTemplatePath(serviceGroup, locale);
        return renderer.render(templatePath, statusData.toString());
    }

    private String resolveTemplatePath(String serviceGroup, String locale) {
        // Sanitize serviceGroup to prevent directory traversal
        String sanitizedGroup = serviceGroup.replaceAll("[^a-zA-Z0-9_-]", "");
        // Strictly validate locale against BCP-47 format
        String resolvedLocale = normalizeLocale(locale);
        return TEMPLATE_BASE + "/" + sanitizedGroup + "/" + resolvedLocale + ".shtml";
    }

    private String normalizeLocale(String locale) {
        // Strict BCP-47 validation: only allow alphanumeric and hyphens
        // Format: language-region (e.g., en-US, fr-FR)
        if (locale == null || locale.isEmpty()) {
            return "en-US";
        }
        // Whitelist only valid BCP-47 characters
        String sanitized = locale.replaceAll("[^a-zA-Z0-9-]", "");
        // Enforce maximum length to prevent abuse
        if (sanitized.length() > 10) {
            sanitized = sanitized.substring(0, 10);
        }
        return sanitized;
    }

    public static class TemplateRenderer {
        private static final Pattern INCLUDE_DIRECTIVE = Pattern.compile(
                "<!--#include\\s+(virtual|file)=\"([^\"]+)\"\\s*-->");

        public String render(String templatePath, String data) {
            try {
                Path path = Paths.get(templatePath).normalize();
                // Verify the resolved path is within the template base
                if (!path.startsWith(TEMPLATE_BASE_STATIC)) {
                    return generateDefaultStatus(data);
                }
                if (!Files.exists(path)) {
                    return generateDefaultStatus(data);
                }
                String template = new String(Files.readAllBytes(path), StandardCharsets.UTF_8);
                // Process SSI directives for template composition
                template = processIncludes(template, path.getParent());
                return template.replace("{{STATUS_DATA}}", escapeHtml(data));
            } catch (IOException e) {
                return generateDefaultStatus(data);
            }
        }

        private String processIncludes(String content, Path basePath) {
            var matcher = INCLUDE_DIRECTIVE.matcher(content);
            StringBuffer result = new StringBuffer();
            while (matcher.find()) {
                String includeType = matcher.group(1);
                String includePath = matcher.group(2);
                String included = resolveInclude(includeType, includePath, basePath);
                matcher.appendReplacement(result, included.replace("$", "\\$"));
            }
            matcher.appendTail(result);
            return result.toString();
        }

        private String resolveInclude(String type, String path, Path basePath) {
            try {
                Path resolved;
                if ("virtual".equals(type)) {
                    resolved = Paths.get(TEMPLATE_BASE_STATIC, path).normalize();
                } else {
                    resolved = basePath.resolve(path).normalize();
                }
                // Ensure included files are within the template directory
                if (!resolved.startsWith(TEMPLATE_BASE_STATIC)) {
                    return "<!-- include error: access denied -->";
                }
                if (Files.exists(resolved)) {
                    return new String(Files.readAllBytes(resolved), StandardCharsets.UTF_8);
                }
            } catch (IOException e) {
                // fall through
            }
            return "<!-- include error -->";
        }

        private static final String TEMPLATE_BASE_STATIC = "/opt/cloudinfra/templates";

        private String generateDefaultStatus(String data) {
            return "<html><body><pre>" + escapeHtml(data) + "</pre></body></html>";
        }

        private String escapeHtml(String input) {
            return input.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;");
        }
    }

    public static class CircuitState {
        private volatile String state = "CLOSED";
        private final AtomicInteger failureCount = new AtomicInteger(0);
        private final AtomicLong lastFailureTime = new AtomicLong(0);

        public boolean isOpen() { return "OPEN".equals(state); }
        public boolean shouldAttemptReset() {
            return System.currentTimeMillis() - lastFailureTime.get() > RECOVERY_TIMEOUT_MS;
        }
        public void toHalfOpen() { state = "HALF_OPEN"; }
        public void toOpen() { state = "OPEN"; lastFailureTime.set(System.currentTimeMillis()); }
        public void recordSuccess() { state = "CLOSED"; failureCount.set(0); }
        public void recordFailure() { failureCount.incrementAndGet(); lastFailureTime.set(System.currentTimeMillis()); }
        public int getFailureCount() { return failureCount.get(); }
        public String getStateName() { return state; }
    }
}
